import React, { useState } from 'react';
import toast from 'react-hot-toast';
import { sendEmails } from '../services/api';
import { Mail, KeyRound, Send, CheckCircle, XCircle } from 'lucide-react';

export default function GmailSettings({
  gmailUser, setGmailUser,
  gmailPassword, setGmailPassword,
  matchedResults,
  onSendComplete,
}) {
  const [sending, setSending] = useState(false);
  const [progress, setProgress] = useState(null);

  const handleSend = async () => {
    if (!gmailUser) return toast.error('Please enter your Gmail address');
    if (!gmailPassword) return toast.error('Please enter your Gmail App Password');
    if (!matchedResults?.length) return toast.error('No matched parties to email');

    const confirmed = window.confirm(
      `You are about to send emails to ${matchedResults.length} parties.\n\nThis action cannot be undone. Continue?`
    );
    if (!confirmed) return;

    setSending(true);
    setProgress({ status: 'sending', message: 'Sending emails… (this may take a few minutes due to SMTP throttling)' });

    try {
      const res = await sendEmails(gmailUser, gmailPassword, matchedResults);
      const data = res.data.data;
      setProgress({
        status: 'done',
        sentCount: data.sentCount,
        failedCount: data.failedCount,
        results: data.results,
      });
      onSendComplete(data);
      toast.success(`✅ Done! Sent: ${data.sentCount}, Failed: ${data.failedCount}`);
    } catch (err) {
      const msg = err.response?.data?.message || 'Failed to send emails';
      toast.error(msg);
      setProgress({ status: 'error', message: msg });
    } finally {
      setSending(false);
    }
  };

  return (
    <div className="gmail-settings">
      <div className="form-row">
        <div className="form-group flex-1">
          <label><Mail size={14} /> Gmail Address</label>
          <input
            type="email"
            placeholder="yourname@gmail.com"
            value={gmailUser}
            onChange={e => setGmailUser(e.target.value)}
            disabled={sending}
          />
        </div>
        <div className="form-group flex-1">
          <label><KeyRound size={14} /> App Password</label>
          <input
            type="password"
            placeholder="Gmail App Password (not your main password)"
            value={gmailPassword}
            onChange={e => setGmailPassword(e.target.value)}
            disabled={sending}
          />
          <small>
            Generate at: Google Account → Security → 2FA → App Passwords
          </small>
        </div>
      </div>

      {gmailUser && gmailPassword && (
        <button
          className="btn btn-send"
          onClick={handleSend}
          disabled={sending || !matchedResults?.length}
        >
          {sending ? <span className="spinner-sm" /> : <Send size={16} />}
          {sending
            ? 'Sending Emails…'
            : `Send Emails to ${matchedResults?.length || 0} Parties`}
        </button>
      )}

      {progress && (
        <div className="send-progress">
          {progress.status === 'sending' && (
            <div className="alert alert-info">
              <span className="spinner-sm" />
              {progress.message}
            </div>
          )}
          {progress.status === 'done' && (
            <div>
              <div className="alert alert-success">
                <CheckCircle size={16} />
                Email batch complete — Sent: <strong>{progress.sentCount}</strong>, Failed: <strong>{progress.failedCount}</strong>
              </div>
              {progress.results?.filter(r => r.status === 'failed').length > 0 && (
                <div className="failed-list">
                  <strong>Failed parties:</strong>
                  {progress.results.filter(r => r.status === 'failed').map((r, i) => (
                    <div key={i} className="failed-item">
                      <XCircle size={14} /> {r.partyName} — {r.error}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
          {progress.status === 'error' && (
            <div className="alert alert-danger">
              <XCircle size={16} />
              {progress.message}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
